function PTNV_ActPage(p)
	PTNV_Load()
	local a = PTNV_Active()
	if a.n == 0 then
		Say(PTNV_TM_NONE, 2, PTNV_T_BACK .. "/main", PTNV_T_CLOSE .. "/PTNV_No")
		return
	end
	local first, last, more = PTNV_Span(a.n, p)
	local o = {}
	local n = 0
	local i = first
	while i <= last do
		local e = a[i]
		local s = PTNV_CH[e.c].title .. ": "
		local tg = PTNV_Target(e.r)
		if tg > 0 then s = s .. PTNV_DS[tg].nm else s = s .. e.r.txt end
		n = n + 1
		o[n] = PTNV_Clip(s, 58) .. "/PTNV_A" .. i
		i = i + 1
	end
	if more then n = n + 1 o[n] = PTNV_T_NEXT .. "/PTNV_AP" .. (p + 1) end
	if p > 1 then n = n + 1 o[n] = PTNV_T_BACK .. "/PTNV_AP" .. (p - 1)
	else n = n + 1 o[n] = PTNV_T_BACK .. "/main" end
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTNV_No"
	PTNV_Say(PTNV_TM_CURTITLE, o)
end

function PTNV_Act(i)
	PTNV_Load()
	local a = PTNV_Active()
	local e = a[i]
	if not e then PTNV_ActPage(1) return end
	local o = {}
	local n = 0
	local s = PTNV_StepText(e)
	local tg = PTNV_Target(e.r)
	if tg > 0 then
		n = n + 1
		o[n] = PTNV_Clip(PTNV_TM_GOTO .. PTNV_DS[tg].nm, 58) .. "/PTNV_AG" .. i
		if e.r.farm and e.r.farm > 0 and e.r.farm ~= tg then
			n = n + 1
			o[n] = PTNV_Clip(PTNV_TM_GOFARM .. PTNV_DS[e.r.farm].nm, 58) .. "/PTNV_AF" .. i
		end
		if e.r.dest and e.r.dest > 0 and e.r.dest ~= tg then
			n = n + 1
			o[n] = PTNV_Clip(PTNV_TM_GONPC .. PTNV_DS[e.r.dest].nm, 58) .. "/PTNV_AN" .. i
		end
	else
		s = s .. " " .. PTNV_TM_NONPC
	end
	n = n + 1 o[n] = PTNV_TQ_DETAIL .. "/PTNV_AD" .. i
	n = n + 1 o[n] = PTNV_T_BACK .. "/PTNV_AP" .. (floor((i - 1) / 4) + 1)
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTNV_No"
	PTNV_Say(PTNV_Clip(s, 500), o)
end

-- which: 1 = where the step sends the player now (PTNV_Target), 2 = bai quai, 3 = NPC
function PTNV_ActGo(i, which)
	PTNV_Load()
	local a = PTNV_Active()
	local e = a[i]
	if not e then return end
	local d = PTNV_Target(e.r)
	if which == 2 then d = e.r.farm end
	if which == 3 then d = e.r.dest end
	if d and d > 0 then PTNV_Go(d) end
end

