	dofile("script\\phongthan\\item\\nhiemvu_detail.lua")
	if PTNV_DetailData then PTNV_DetailData() end
	if not PTNV_F11 then PTNV_F11 = {} PTNV_RW = {} PTNV_MN = {} end
