-- entries of group g for this player: quests of the group (own camp; main story: all camps, own first) + NPC list
function PTNV_GList(g)
	local camp = PTNV_Camp()
	local o = {}
	local n = 0
	local pass = 1
	while pass <= 2 do
		local q = 1
		while q <= PTNV_NQ do
			local Q = PTNV_Q[q]
			if Q.g == g then
				local mine = Q.cp < 0 or Q.cp == camp
				if (pass == 1 and mine) or (pass == 2 and not mine and Q.c == 20) then
					n = n + 1
					o[n] = q
				end
			end
			q = q + 1
		end
		pass = pass + 1
	end
	n = n + 1
	o[n] = 0
	o.n = n
	return o
end

function PTNV_GOpen(g)
	PTNV_Load()
	local c = PTNV_Ctx()
	c.g = g
	c.gp = 1
	PTNV_GPage()
end

function PTNV_GPage()
	PTNV_Load()
	local c = PTNV_Ctx()
	local t = PTNV_GList(c.g)
	local first, last, more = PTNV_Span(t.n, c.gp)
	local o = {}
	local n = 0
	local i = first
	while i <= last do
		local s = PTNV_TQ_NPCS
		if t[i] > 0 then
			local Q = PTNV_Q[t[i]]
			s = Q.title
			if PTNV_QCur(t[i]) > 0 then s = "[>] " .. s end
		end
		n = n + 1
		o[n] = PTNV_Clip(s, 60) .. "/PTNV_GE" .. (i - first + 1)
		i = i + 1
	end
	if more then n = n + 1 o[n] = PTNV_T_NEXT .. "/PTNV_GNX" end
	n = n + 1 o[n] = PTNV_T_BACK .. "/PTNV_GBK"
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTNV_No"
	PTNV_Say("<color=yellow>" .. PTNV_GR[c.g].title .. PTNV_TQ_QHINT, o)
end

function PTNV_GE(i)
	PTNV_Load()
	local c = PTNV_Ctx()
	if not c.g then return end
	local t = PTNV_GList(c.g)
	local first = PTNV_Span(t.n, c.gp)
	local q = t[first + i - 1]
	if not q then return end
	if q == 0 then PTNV_Page(c.g, 1) return end
	c.from = "g"
	PTNV_QOpen(q)
end

function PTNV_GNX() local c = PTNV_Ctx() c.gp = (c.gp or 1) + 1 PTNV_GPage() end
function PTNV_GBK()
	local c = PTNV_Ctx()
	if c.gp and c.gp > 1 then c.gp = c.gp - 1 PTNV_GPage() else PTNV_Main() end
end

-- does step s (rows: real rows of the chain or pseudo rows) match the player's task variables now
function PTNV_SMatch(s, camp, lv)
	local j = 1
	while j <= s.rows.n do
		if PTNV_Match(s.rows[j], camp, lv) then return 1 end
		j = j + 1
	end
	return nil
end

-- current step index of quest q (0 = none / other camp); second result 1 = every step done
function PTNV_QCur(q)
	local Q = PTNV_Q[q]
	local camp = PTNV_Camp()
	if Q.cp >= 0 and Q.cp ~= camp then return 0, nil end
	local lv = GetLevel()
	local k = 1
	while k <= Q.n do
		if PTNV_SMatch(Q.s[k], camp, lv) then return k, nil end
		k = k + 1
	end
	if Q.var and Q.var > 0 and GetTask(Q.var) > Q.maxhi then return 0, 1 end
	return 0, nil
end

function PTNV_QOpen(q)
	PTNV_Load()
	local c = PTNV_Ctx()
	c.q = q
	local Q = PTNV_Q[q]
	local cur = PTNV_QCur(q)
	local p = 1
	if cur > 0 then
		while 1 do
			local first, last, more = PTNV_Span(Q.n, p)
			if cur <= last or not more then break end
			p = p + 1
		end
	end
	c.qp = p
	PTNV_QPage()
end

function PTNV_QPage()
	PTNV_Load()
	local c = PTNV_Ctx()
	local Q = PTNV_Q[c.q]
	local cur, all = PTNV_QCur(c.q)
	local first, last, more = PTNV_Span(Q.n, c.qp)
	local o = {}
	local n = 0
	local k = first
	while k <= last do
		local s = Q.s[k]
		local mk = "[ ] "
		if k == cur then mk = "[>] " elseif all or (cur > 0 and k < cur) then mk = "[x] " end
		local tail = ""
		if s.lv > 0 then tail = " (" .. s.lv .. ")" end
		n = n + 1
		o[n] = PTNV_Clip(mk .. k .. ". " .. s.txt, 62 - strlen(tail)) .. tail .. "/PTNV_QE" .. (k - first + 1)
		k = k + 1
	end
	if more then n = n + 1 o[n] = PTNV_T_NEXT .. "/PTNV_QN" end
	n = n + 1 o[n] = PTNV_T_BACK .. "/PTNV_QB"
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTNV_No"
	PTNV_Say("<color=yellow>" .. Q.title .. PTNV_TQ_QHINT, o)
end

function PTNV_QE(i)
	local c = PTNV_Ctx()
	if not c.q then return end
	PTNV_Load()
	local Q = PTNV_Q[c.q]
	local first = PTNV_Span(Q.n, c.qp)
	local k = first + i - 1
	if k > Q.n then return end
	PTNV_SDOpen(c.q, k)
end

function PTNV_QN() local c = PTNV_Ctx() c.qp = (c.qp or 1) + 1 PTNV_QPage() end
function PTNV_QB()
	local c = PTNV_Ctx()
	if c.qp and c.qp > 1 then c.qp = c.qp - 1 PTNV_QPage() return end
	if c.from == "g" and c.g then PTNV_GPage() else PTNV_Main() end
end

-- destinations offered for step k of quest q: static targets + the target of the matching row / custom row
function PTNV_STargets(q, k)
	local Q = PTNV_Q[q]
	local s = Q.s[k]
	local o = {}
	local n = 0
	local camp = PTNV_Camp()
	local lv = GetLevel()
	local dy = 0
	if s.dyn == "row" then
		local j = 1
		while j <= s.rows.n and dy == 0 do
			if PTNV_Match(s.rows[j], camp, lv) then dy = PTNV_Target(s.rows[j]) end
			j = j + 1
		end
	elseif s.dyn then
		local f = getglobal(s.dyn)
		local r = f and f(camp, lv)
		if r and PTNV_SMatch(s, camp, lv) then dy = PTNV_Target(r) end
	end
	if dy and dy > 0 then n = n + 1 o[n] = dy end
	local j = 1
	while j <= s.t.n and n < 4 do
		if s.t[j] ~= dy then n = n + 1 o[n] = s.t[j] end
		j = j + 1
	end
	o.n = n
	return o
end

-- append text s to line list L, wrapped at spaces into lines of at most 100 bytes
function PTNV_Wrap(L, s)
	while strlen(s) > 100 do
		local cut = 100
		while cut > 40 and strsub(s, cut, cut) ~= " " do cut = cut - 1 end
		L.n = L.n + 1
		L[L.n] = strsub(s, 1, cut)
		s = strsub(s, cut + 1)
	end
	L.n = L.n + 1
	L[L.n] = s
end

function PTNV_Pos(d)
	local mn = PTNV_MN[d.map] or ("" .. d.map)
	return " - " .. mn .. " " .. floor(d.nx / 8) .. "." .. floor(d.ny / 16)
end

function PTNV_DLines(q, k)
	PTNV_LoadDetail()
	local Q = PTNV_Q[q]
	local s = Q.s[k]
	local L = {}
	L.n = 0
	local cur, all = PTNV_QCur(q)
	local st = PTNV_TQ_TODO
	if k == cur then st = PTNV_TQ_CUR elseif all or (cur > 0 and k < cur) then st = PTNV_TQ_DONE end
	if Q.cp >= 0 and Q.cp ~= PTNV_Camp() then st = " " .. PTNV_TQ_OTHER end
	PTNV_Wrap(L, Q.title .. " - " .. PTNV_TQ_STEP .. k .. "/" .. Q.n .. st)
	PTNV_Wrap(L, PTNV_TQ_JOB .. s.txt)
	local f = PTNV_F11[q * 1000 + k]
	if f then PTNV_Wrap(L, PTNV_TQ_F11 .. f) end
	local t = PTNV_STargets(q, k)
	local j = 1
	while j <= t.n do
		local d = PTNV_DS[t[j]]
		if d.kind == 1 then
			local x = PTNV_TQ_MOB .. d.nm
			if d.mlv and d.mlv > 0 then x = x .. PTNV_TQ_LVQ .. d.mlv end
			PTNV_Wrap(L, x .. PTNV_Pos(d))
		else
			PTNV_Wrap(L, PTNV_TQ_NPC .. d.nm .. PTNV_Pos(d))
		end
		if d.gate > 0 and not PTNV_Gate(d.gate) then PTNV_Wrap(L, PTNV_TQ_LOCK .. (PTNV_GATEMSG[d.gate] or "")) end
		j = j + 1
	end
	if t.n == 0 and s.dyn then PTNV_Wrap(L, PTNV_TQ_NODYN) end
	local IS = PTNV_IS[s.set]
	if s.set > 0 and IS then
		local r = {}
		r.set = s.set
		local nd = PTNV_Need(r)
		local i = 1
		while i <= nd.n do
			PTNV_Wrap(L, PTNV_TQ_NEED .. nd[i].it.nm .. PTNV_TQ_HAVE .. nd[i].have .. PTNV_TQ_NEEDN .. nd[i].it.n)
			i = i + 1
		end
	end
	if s.kill == 1 then PTNV_Wrap(L, PTNV_TQ_FIGHT) end
	local cd = PTNV_TQ_COND .. s.lv
	if Q.cp >= 0 then cd = cd .. PTNV_TQ_CAMP .. getglobal("PTNV_TQ_CAMP" .. Q.cp) end
	PTNV_Wrap(L, cd)
	if PTNV_RW[q] then PTNV_Wrap(L, PTNV_TQ_RW .. PTNV_RW[q]) end
	return L
end

-- detail pages: lines up to 420 bytes per page
function PTNV_DSplit(L)
	local P = {}
	P.n = 1
	P[1] = ""
	local i = 1
	while i <= L.n do
		local cur = P[P.n]
		if cur ~= "" and strlen(cur) + strlen(L[i]) + 7 > 420 then
			P.n = P.n + 1
			P[P.n] = L[i]
		elseif cur == "" then P[P.n] = L[i]
		else P[P.n] = cur .. "<enter>" .. L[i] end
		i = i + 1
	end
	return P
end

function PTNV_SDOpen(q, k)
	local c = PTNV_Ctx()
	c.q = q
	c.k = k
	c.dp = 1
	PTNV_DPage()
end

function PTNV_DPage()
	PTNV_Load()
	local c = PTNV_Ctx()
	local P = PTNV_DSplit(PTNV_DLines(c.q, c.k))
	if c.dp > P.n then c.dp = P.n end
	local o = {}
	local n = 0
	if c.dp < P.n then n = n + 1 o[n] = PTNV_TQ_MORE .. (c.dp + 1) .. PTNV_TQ_OF .. P.n .. ")/PTNV_DN" end
	local t = PTNV_STargets(c.q, c.k)
	local j = 1
	while j <= t.n do
		n = n + 1
		o[n] = PTNV_Clip(PTNV_TQ_GO .. PTNV_DS[t[j]].nm, 60) .. "/PTNV_DG" .. j
		j = j + 1
	end
	n = n + 1 o[n] = PTNV_T_BACK .. "/PTNV_DB"
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTNV_No"
	PTNV_Say(P[c.dp], o)
end

function PTNV_DN() local c = PTNV_Ctx() c.dp = (c.dp or 1) + 1 PTNV_DPage() end
function PTNV_DB()
	local c = PTNV_Ctx()
	if c.q then
		local Q = PTNV_Q[c.q]
		local p = 1
		while 1 do
			local first, last, more = PTNV_Span(Q.n, p)
			if c.k <= last or not more then break end
			p = p + 1
		end
		c.qp = p
		PTNV_QPage()
	else PTNV_Main() end
end

function PTNV_DG(j)
	PTNV_Load()
	local c = PTNV_Ctx()
	if not c.q then return end
	local t = PTNV_STargets(c.q, c.k)
	if t[j] then PTNV_Go(t[j]) end
end

-- from Nhiem vu dang lam: the step of the active entry i
function PTNV_AD(i)
	PTNV_Load()
	local a = PTNV_Active()
	local e = a[i]
	if not e then return end
	local camp = PTNV_Camp()
	local lv = GetLevel()
	local q = 1
	while q <= PTNV_NQ do
		local Q = PTNV_Q[q]
		if Q.c == e.c and (Q.cp < 0 or Q.cp == camp) then
			local k = 1
			while k <= Q.n do
				local s = Q.s[k]
				local j = 1
				while j <= s.rows.n do
					if s.rows[j] == e.r then PTNV_Ctx().from = "a" PTNV_Ctx().q = q PTNV_SDOpen(q, k) return end
					j = j + 1
				end
				k = k + 1
			end
			k = PTNV_QCur(q)
			if k > 0 then PTNV_Ctx().from = "a" PTNV_SDOpen(q, k) return end
		end
		q = q + 1
	end
end

